 static final class Call{final String method,path;final JSONObject body;Call(String m,String p,JSONObject b){method=m;path=p;body=b;}}
 public static class TestActivity extends MainActivity{
  boolean acceptStart=true,failRequests=false;final List<Call> calls=new CopyOnWriteArrayList<>();final List<Intent> starts=new CopyOnWriteArrayList<>(),stops=new CopyOnWriteArrayList<>(),opened=new CopyOnWriteArrayList<>(),pickers=new CopyOnWriteArrayList<>();int pickerRequest=-1;volatile CountDownLatch latch=new CountDownLatch(1);
  @Override protected JSONObject request(String method,String path,JSONObject body)throws Exception{calls.add(new Call(method,path,body));latch.countDown();if(failRequests)throw new java.io.IOException("Local controller stopped");if(path.startsWith("/updates"))return new JSONObject("{\"authState\":\"error\",\"lastError\":\"403 Forbidden {}\",\"lastPhase\":\"xbox-title-token\",\"diagnostics\":{\"phase\":\"xbox-title-token\",\"authState\":\"error\",\"failure\":{\"phase\":\"xbox-title-token\",\"httpStatus\":403}}}");if(path.equals("/catalog"))return new JSONObject("{\"catalog\":[{\"id\":\"look\",\"label\":\"Look around\",\"fields\":[],\"note\":\"\"}],\"options\":{}}");if(path.equals("/status"))return new JSONObject("{\"authChallenge\":{\"userCode\":\"ABC123\"},\"survival\":{\"language\":{\"bundledWords\":5000},\"vocabulary\":{\"count\":2,\"actions\":{\"dredge\":\"dig\"},\"materials\":{\"rubble\":\"cobblestone\"}},\"learning\":{\"confirmed\":3,\"blocked\":1}}}");if(path.equals("/diagnostics"))return new JSONObject("{\"phase\":\"account-or-realm-discovery\",\"failure\":{\"httpStatus\":403}}");if(path.equals("/mode"))return new JSONObject("{\"accepted\":true,\"queued\":true,\"message\":\"Requested mode; waiting for server confirmation.\"}");if(path.equals("/plans"))return new JSONObject("{\"plans\":{\"cards\":[{\"id\":7,\"label\":\"Inventory\",\"state\":\"completed\",\"command\":\"inventory\",\"note\":\"\",\"result\":\"done\",\"descriptor\":{\"id\":\"inventory\",\"values\":{}}}],\"selected\":7}}");if(path.equals("/plans/prepare"))return new JSONObject("{\"accepted\":true,\"message\":\"Saved and selected plan #17.\",\"plans\":{\"cards\":[{\"id\":17,\"label\":\"Inventory\",\"state\":\"waiting\",\"command\":\"inventory\",\"note\":\"\",\"result\":\"\",\"descriptor\":{\"id\":\"inventory\",\"values\":{}}}],\"selected\":17}}");if(path.startsWith("/plans/"))return new JSONObject("{\"accepted\":true,\"message\":\"Plan action accepted.\",\"plans\":{\"cards\":[],\"selected\":17}}");if(path.startsWith("/stop"))return new JSONObject("{\"message\":\"Stopped.\",\"plans\":{\"cards\":[],\"selected\":0}}");if(path.equals("/message"))return new JSONObject("{\"accepted\":false,\"message\":\"Unsupported command. Use Commands.\"}");return new JSONObject("{}");}
  @Override public ComponentName startService(Intent i){if("STOP".equals(i.getAction()))stops.add(i);return new ComponentName(this,BotService.class);}@Override public ComponentName startForegroundService(Intent i){starts.add(i);return acceptStart?new ComponentName(this,BotService.class):null;}@Override public void startActivity(Intent i){opened.add(i);}@Override public void startActivityForResult(Intent i,int request){pickers.add(i);pickerRequest=request;}void expect(){latch=new CountDownLatch(1);}void await()throws Exception{assertTrue("Expected local API action",latch.await(3,TimeUnit.SECONDS));for(int i=0;i<4;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(20);}}Call last(){return calls.get(calls.size()-1);}
 }
 TestActivity a;@Before public void create(){a=Robolectric.buildActivity(TestActivity.class).setup().get();a.onPause();}@After public void destroy(){a.onDestroy();}
 View find(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View x=find(g.getChildAt(i),label);if(x!=null)return x;}}return null;}AlertDialog settings(){a.showSettings();Shadows.shadowOf(Looper.getMainLooper()).idle();return ShadowAlertDialog.getLatestAlertDialog();}
 @Test public void servicePowerStartsOnceAndStopServiceSendsAndroidStop(){a.botField.setText("RealmBot");a.ownerField.setText("RealmOwner");AlertDialog d=settings();find(d.getWindow().getDecorView(),"Start bot").performClick();assertEquals(1,a.starts.size());assertTrue(a.serviceStarted);assertEquals("Cancel bot service startup",a.powerButton.getContentDescription());find(d.getWindow().getDecorView(),"Start bot").performClick();assertEquals(1,a.starts.size());find(d.getWindow().getDecorView(),"Stop bot service").performClick();assertEquals(1,a.stops.size());assertEquals("STOP",a.stops.get(0).getAction());assertFalse(a.serviceStarted);assertEquals("Start bot service",a.powerButton.getContentDescription());d.dismiss();}
 @Test public void rejectedAndroidStartIsNotReportedAsRunning(){a.botField.setText("RealmBot");a.ownerField.setText("RealmOwner");a.acceptStart=false;a.startBot();assertFalse(a.serviceStarted);assertEquals("Start bot service",a.powerButton.getContentDescription());}
