 @Test public void microsoftCodeCopyAndClickableLinkAreVisibleOnHome()throws Exception{a.apiConnected=true;a.serviceStarted=true;a.token="m".repeat(64);AlertDialog d=settings();a.expect();find(d.getWindow().getDecorView(),"Microsoft sign-in code").performClick();a.await();assertEquals(View.VISIBLE,a.authCodeLabel.getVisibility());assertEquals(View.VISIBLE,a.copyAuthCode.getVisibility());assertNotNull(a.authCodeLabel.getParent());Spanned text=(Spanned)a.authCodeLabel.getText();URLSpan[] links=text.getSpans(0,text.length(),URLSpan.class);assertEquals(1,links.length);assertEquals("https://www.microsoft.com/link",links[0].getURL());links[0].onClick(a.authCodeLabel);assertEquals(Intent.ACTION_VIEW,a.opened.get(0).getAction());assertEquals(Uri.parse("https://www.microsoft.com/link"),a.opened.get(0).getData());a.copyAuthCode.performClick();ClipboardManager cb=(ClipboardManager)a.getSystemService(android.content.Context.CLIPBOARD_SERVICE);assertEquals("ABC123",cb.getPrimaryClip().getItemAt(0).getText().toString());d.dismiss();}
 @Test public void shareFileUsesAndroidPickerAndSharesOnlyChosenUriReadOnly()throws Exception{AlertDialog d=settings();View share=find(d.getWindow().getDecorView(),"Share one file…");assertNotNull(share);share.performClick();assertEquals(1,a.pickers.size());Intent picker=a.pickers.get(0);assertEquals(Intent.ACTION_OPEN_DOCUMENT,picker.getAction());assertTrue(picker.hasCategory(Intent.CATEGORY_OPENABLE));assertEquals("*/*",picker.getType());assertEquals(MainActivity.REQUEST_PICK_SHARED_FILE,a.pickerRequest);android.content.pm.PackageInfo pkg=a.getPackageManager().getPackageInfo(a.getPackageName(),android.content.pm.PackageManager.GET_PERMISSIONS);List<String> perms=pkg.requestedPermissions==null?Collections.emptyList():Arrays.asList(pkg.requestedPermissions);assertFalse(perms.contains("android.permission.READ_EXTERNAL_STORAGE"));assertFalse(perms.contains("android.permission.MANAGE_EXTERNAL_STORAGE"));d.dismiss();a.onActivityResult(a.pickerRequest,android.app.Activity.RESULT_CANCELED,null);assertTrue(a.opened.isEmpty());Uri chosen=Uri.parse("content://com.android.providers.downloads.documents/document/42");a.onActivityResult(a.pickerRequest,android.app.Activity.RESULT_OK,new Intent().setData(chosen));assertEquals(1,a.opened.size());Intent chooser=a.opened.get(0);assertEquals(Intent.ACTION_CHOOSER,chooser.getAction());Intent send=(Intent)chooser.getParcelableExtra(Intent.EXTRA_INTENT);assertNotNull(send);assertEquals(Intent.ACTION_SEND,send.getAction());assertEquals(chosen,send.getParcelableExtra(Intent.EXTRA_STREAM));assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertFalse((send.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0);assertEquals(chosen,send.getClipData().getItemAt(0).getUri());}
